{ "explanation": "For a quadratic ax² + bx + c, the roots come from the quadratic formula, and the quantity under the square root — the discriminant Δ = b² − 4ac — controls everything. If Δ > 0 the square root is real and nonzero, giving two distinct roots (the parabola crosses the x-axis twice); if Δ = 0 the ± vanishes, giving one repeated root (the parabola is tangent to the axis); if Δ < 0 the square root is imaginary, so there are no real roots (the parabola never touches the axis). Use the sliders for a, b, and c (or the preset buttons) to watch the parabola, the value of Δ, and the root count change together.", "manimCode": "// ---------- Axes ----------
const axes = new Axes({
  xRange: [-4, 4, 1],
  yRange: [-5, 5, 1],
  xLength: 6.4,
  yLength: 4.8,
  tips: true
});
axes.moveTo([-1.0, -0.15, 0]);

// ---------- State ----------
let A = 1, B = -1, C = -2;
let curve = null;
let rootDots = [];
let eqText = null;
let discText = null;
let statusText = null;

function fmt(v) {
  let r = Math.round(v * 10) / 10;
  if (Object.is(r, -0)) r = 0;
  return r.toString().replace('-', '−');
}

function fmt2(v) {
  let r = Math.round(v * 100) / 100;
  if (Object.is(r, -0)) r = 0;
  return r.toString().replace('-', '−');
}

function eqString() {
  if (A === 0) {
    if (B === 0 && C === 0) return 'y = 0';
    let s = 'y = ';
    if (B !== 0) s += (B === 1 ? '' : B === -1 ? '−' : fmt(B)) + 'x';
    if (C !== 0) s += (B !== 0 ? (C > 0 ? ' + ' : ' − ') : (C < 0 ? '−' : '')) + fmt(Math.abs(C));
    return s;
  }
  let s = 'y = ' + (A === 1 ? '' : A === -1 ? '−' : fmt(A)) + 'x²';
  if (B !== 0) s += (B > 0 ? ' + ' : ' − ') + (Math.abs(B) === 1 ? '' : fmt(Math.abs(B))) + 'x';
  if (C !== 0) s += (C > 0 ? ' + ' : ' − ') + fmt(Math.abs(C));
  return s;
}

function replaceLine(oldLine, str, color, y, size) {
  if (oldLine) { scene.remove(oldLine); }
  const t = new Text({ text: str, color: color, fontSize: size });
  t.moveTo([-0.8, y, 0]);
  scene.add(t);
  return t;
}

function refresh() {
  let D = B * B - 4 * A * C;
  if (A !== 0 && Math.abs(D) <= 0.11) D = 0; // snap so tangency is easy to find

  let mode = 'two';
  let col = GREEN;
  if (A === 0) { mode = 'linear'; col = GRAY; }
  else if (D > 0) { mode = 'two'; col = GREEN; }
  else if (D < 0) { mode = 'none'; col = RED; }
  else { mode = 'one'; col = GOLD; }

  // Parabola (remove old, plot new)
  if (curve) { scene.remove(curve); }
  curve = axes.plot(function (x) { return A * x * x + B * x + C; }, { color: col, numSamples: 400 });
  scene.add(curve);

  // Root dots
  for (let i = 0; i < rootDots.length; i++) { scene.remove(rootDots[i]); }
  rootDots = [];

  let statusStr = '';
  if (mode === 'two') {
    const s = Math.sqrt(D);
    const r1 = Math.min((-B - s) / (2 * A), (-B + s) / (2 * A));
    const r2 = Math.max((-B - s) / (2 * A), (-B + s) / (2 * A));
    const rs = [r1, r2];
    for (let i = 0; i < rs.length; i++) {
      if (Math.abs(rs[i]) <= 4.3) {
        const d = new Dot({ point: axes.c2p(rs[i], 0), color: col });
        rootDots.push(d);
        scene.add(d);
      }
    }
    statusStr = 'Two real roots:  x₁ = ' + fmt2(r1) + ',   x₂ = ' + fmt2(r2);
  } else if (mode === 'one') {
    const r = -B / (2 * A);
    if (Math.abs(r) <= 4.3) {
      const d = new Dot({ point: axes.c2p(r, 0), color: col, radius: 0.12 });
      rootDots.push(d);
      scene.add(d);
    }
    statusStr = 'One repeated root:  x = ' + fmt2(r) + '  — tangent to the x-axis';
  } else if (mode === 'none') {
    const re = -B / (2 * A);
    const im = Math.sqrt(-D) / Math.abs(2 * A);
    statusStr = 'No real roots — complex pair:  ' + fmt2(re) + ' ± ' + fmt2(im) + 'i';
  } else {
    statusStr = 'a = 0 makes a straight line — choose a ≠ 0 for a parabola';
  }

  eqText = replaceLine(eqText, eqString(), WHITE, -2.95, 24);
  discText = replaceLine(discText, 'Δ = b² − 4ac = ' + fmt2(D), col, -3.38, 24);
  statusText = replaceLine(statusText, statusStr, col, -3.78, 21);
}

// ---------- Title & formula ----------
const title = new Text({ text: 'The Discriminant  Δ = b² − 4ac', color: WHITE, fontSize: 30 });
title.moveTo([-2.4, 3.6, 0]);
await scene.play(new Write(title));

const formula = new MathTex({ latex: 'x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}' });
await formula.waitForRender();
formula.moveTo([-2.4, 2.9, 0]);
await scene.play(new Write(formula));

const sub = new Text({ text: 'Sign of Δ = number of x-axis crossings', color: GRAY, fontSize: 18 });
sub.moveTo([-2.4, 2.4, 0]);
scene.add(sub);

// ---------- Axes intro ----------
await scene.play(new Create(axes));
scene.add(axes.getAxisLabels());

refresh();
await scene.wait(0.5);

// ---------- Controls ----------
const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'a — steepness', min: -2, max: 2, value: A, step: 0.1, onChange: function (v) { A = Math.round(v * 100) / 100; refresh(); } });
controls.addSlider({ label: 'b — tilt / shift', min: -4, max: 4, value: B, step: 0.1, onChange: function (v) { B = Math.round(v * 100) / 100; refresh(); } });
controls.addSlider({ label: 'c — up / down', min: -4, max: 4, value: C, step: 0.1, onChange: function (v) { C = Math.round(v * 100) / 100; refresh(); } });
controls.addButton({ label: '2 roots preset', onClick: function () { A = 1; B = -1; C = -2; refresh(); } });
controls.addButton({ label: '1 root (tangent)', onClick: function () { A = 1; B = 2; C = 1; refresh(); } });
controls.addButton({ label: '0 real roots', onClick: function () { A = 1; B = 0; C = 2; refresh(); } });

await scene.wait(999999);" }

